import {
  GRADE_REVIEW_CONFIDENCE,
  MISCONCEPTIONS,
  SKILL_BY_CODE,
  type AiGrade,
  type CriterionScore,
  type GradeFlag,
  type GradeIssue,
  type Rubric,
  type SkillEvidence,
  type Tt27Level,
} from '../scoring/contracts.ts';
import { clamp, levelFor, totalFromCriteria } from './rules.ts';

export class GradeParseError extends Error {
  constructor(message = 'AI trả về dữ liệu không đọc được.') {
    super(message);
    this.name = 'GradeParseError';
  }
}

type Json = Record<string, unknown>;
const FLAGS: GradeFlag[] = ['unreadable', 'off-topic', 'possible-copy', 'low-confidence'];

function isObj(v: unknown): v is Json {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

/** Đóng các ngoặc còn mở (JSON bị cắt giữa chừng). Bỏ chuỗi / cặp khoá đang dở. */
export function closeTruncated(t: string): string {
  const stack: string[] = [];
  let inStr = false;
  let esc = false;
  let strStart = -1;
  for (let i = 0; i < t.length; i++) {
    const ch = t[i];
    if (inStr) {
      if (esc) esc = false;
      else if (ch === '\\') esc = true;
      else if (ch === '"') inStr = false;
      continue;
    }
    if (ch === '"') {
      inStr = true;
      strStart = i;
    } else if (ch === '{' || ch === '[') stack.push(ch === '{' ? '}' : ']');
    else if (ch === '}' || ch === ']') stack.pop();
  }
  let out = inStr ? t.slice(0, strStart) : t;
  // Bỏ phần đuôi dở: dấu phẩy, "khoá": chưa có giá trị.
  for (let k = 0; k < 3; k++) out = out.replace(/\s+$/, '').replace(/,$/, '').replace(/"[^"]*"\s*:$/, '').replace(/:$/, '');
  out = out.replace(/,\s*$/, '');
  return out + stack.reverse().join('');
}

/** JSON "lỏng": bỏ ```, chữ thừa trước/sau, dấu phẩy thừa, ngoặc kép cong; đóng ngoặc nếu bị cắt. */
export function parseLooseJson(text: string): { value: unknown; repaired: boolean } {
  let t = (text ?? '').trim();
  const fence = t.match(/```(?:json)?\s*([\s\S]*?)(```|$)/i);
  if (fence) t = fence[1].trim();
  const fenced = !!fence;
  const start = t.indexOf('{');
  if (start < 0) throw new GradeParseError();
  const end = t.lastIndexOf('}');
  const body = end > start ? t.slice(start, end + 1) : t.slice(start);
  try {
    return { value: JSON.parse(body), repaired: fenced || start > 0 || end < t.length - 1 };
  } catch {
    /* sửa tiếp */
  }
  let fixed = body.replace(/[“”]/g, '"').replace(/,\s*([}\]])/g, '$1');
  for (const candidate of [fixed, closeTruncated(t.slice(start).replace(/[“”]/g, '"')).replace(/,\s*([}\]])/g, '$1')]) {
    try {
      return { value: JSON.parse(candidate), repaired: true };
    } catch {
      fixed = candidate;
    }
  }
  throw new GradeParseError();
}

function str(v: unknown, max = 1200): string {
  if (typeof v === 'number') return String(v);
  return typeof v === 'string' ? v.replace(/\s+\n/g, '\n').trim().slice(0, max) : '';
}

function num(v: unknown): number | null {
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  if (typeof v === 'string') {
    const m = v.replace(',', '.').match(/-?\d+(\.\d+)?/);
    if (m) return Number(m[0]);
  }
  return null;
}

const AI_WORDS = /(trí tuệ nhân tạo|máy chấm|mô hình ngôn ngữ|chatbot|trợ lý ảo)/i;
const AI_ACRONYM = /\bA\.?I\b/;
const HARSH: [RegExp, string][] = [
  [/sai bét/gi, 'chưa đúng'],
  [/(^|[\s,.;:!?("“])(sai)(?=$|[\s,.;:!?)"”])/gi, '$1chưa đúng'],
  [/(^|[\s,.;:!?("“])(kém|dở|tệ)(?=$|[\s,.;:!?)"”])/gi, '$1chưa tốt'],
  [/(^|[\s,.;:!?("“])(lười)(?=$|[\s,.;:!?)"”])/gi, '$1chưa chăm'],
  [/(^|[\s,.;:!?("“])(ngu|dốt)(?=$|[\s,.;:!?)"”])/gi, '$1'],
];

function sentences(s: string): string[] {
  // Dấu câu dính liền chữ/số phía sau (6.5, 1.000) không tách câu.
  return (s.match(/(?:[^.!?…]|[.!?…](?=\S))+[.!?…]*/g) ?? []).map((x) => x.trim()).filter(Boolean);
}

/** Lời nhắn cho HS: bỏ câu nhắc tới AI, thay từ nặng nề, tối đa 4 câu. */
export function sanitizeStudentFeedback(s: string): string {
  let out = sentences(s).filter((x) => !AI_WORDS.test(x) && !AI_ACRONYM.test(x));
  out = out.map((x) => HARSH.reduce((acc, [re, rep]) => acc.replace(re, rep), x).replace(/\s{2,}/g, ' ').trim());
  return out.slice(0, 4).join(' ');
}

export function defaultStudentFeedback(level: Tt27Level): string {
  if (level === 'T') return 'Em làm bài rất tốt, trình bày rõ ràng. Em giữ vững phong độ nhé!';
  if (level === 'H') return 'Em đã hoàn thành bài làm, cô khen em cố gắng. Em đọc lại bài một lần nữa để sửa những chỗ chưa đúng nhé!';
  return 'Cô thấy em đã cố gắng làm bài. Em cùng cô xem lại đề bài và làm lại từng bước nhé!';
}

export function defaultParentFeedback(level: Tt27Level): string {
  if (level === 'T') return 'Con làm bài tốt. Bố mẹ khen con và cho con kể lại cách làm của mình nhé.';
  if (level === 'H') return 'Con đã hoàn thành bài, còn vài chỗ cần cẩn thận hơn. Bố mẹ cho con đọc lại bài và tự kiểm tra trong 5 phút.';
  return 'Con cần thêm thời gian cho dạng bài này. Bố mẹ ngồi cùng con đọc lại đề, hỏi con "đề cho biết gì, hỏi gì?" trước khi làm.';
}

export interface ValidateContext {
  rubric: Rubric;
  submissionId: string;
  model: string;
  /** ISO */
  now: string;
  imageCount: number;
  mock?: boolean;
}

export interface ValidateResult {
  grade: AiGrade;
  /** Những chỗ đã phải sửa (để ghi log / hiện cho GV). */
  repairs: string[];
}

/** Kiểm tra + chuẩn hoá đối tượng AI trả về thành AiGrade hợp lệ. Ném GradeParseError nếu không phải đối tượng. */
export function validateAiGrade(raw: unknown, ctx: ValidateContext): ValidateResult {
  if (!isObj(raw)) throw new GradeParseError();
  const repairs: string[] = [];
  const { rubric } = ctx;

  /* ---- tiêu chí ---- */
  const list = Array.isArray(raw.criteria) ? raw.criteria.filter(isObj) : [];
  const used = new Set<number>();
  const criteria: CriterionScore[] = rubric.criteria.map((c, idx) => {
    let i = list.findIndex((x, j) => !used.has(j) && str(x.criterionId ?? x.id, 100) === c.id);
    if (i < 0) i = list.findIndex((x, j) => !used.has(j) && str(x.name, 200).toLowerCase() === c.name.toLowerCase());
    if (i < 0 && list.length === rubric.criteria.length && !used.has(idx)) i = idx;
    const max = Math.max(0, c.points);
    if (i < 0) {
      repairs.push(`thiếu tiêu chí ${c.id}`);
      return { criterionId: c.id, points: 0, max, comment: 'Chưa chấm được tiêu chí này — thầy cô xem giúp.' };
    }
    used.add(i);
    const x = list[i];
    let p = num(x.points ?? x.score);
    if (p === null) {
      repairs.push(`điểm tiêu chí ${c.id} không phải số`);
      p = 0;
    }
    const clamped = Math.round(clamp(p, 0, max) * 2) / 2;
    if (clamped !== p) repairs.push(`kẹp điểm tiêu chí ${c.id}: ${p} → ${clamped}`);
    const evidence = str(x.evidence, 300);
    return { criterionId: c.id, points: clamped, max, comment: str(x.comment, 400) || c.name, ...(evidence ? { evidence } : {}) };
  });
  const { total, max } = totalFromCriteria(criteria.map((c) => c.points), rubric);
  const aiTotal = num(raw.total);
  if (aiTotal !== null && Math.abs(aiTotal - total) > 0.5) repairs.push(`tổng AI ${aiTotal} ≠ tổng tiêu chí ${total}`);
  const level = levelFor(total, max);

  /* ---- chép bài ---- */
  let transcript: string[] = [];
  if (Array.isArray(raw.transcript)) transcript = raw.transcript.map((t) => str(t, 4000)).filter((t) => t !== '');
  else if (typeof raw.transcript === 'string' && raw.transcript.trim()) transcript = [str(raw.transcript, 8000)];
  transcript = transcript.slice(0, Math.max(ctx.imageCount, 0) || transcript.length);

  /* ---- kĩ năng ---- */
  const allowed = new Set(rubric.skills);
  const skills: AiGrade['skills'] = [];
  for (const s of Array.isArray(raw.skills) ? raw.skills : []) {
    const code = isObj(s) ? str(s.code, 60) : str(s, 60);
    if (!code || (!allowed.has(code) && !SKILL_BY_CODE[code]) || skills.some((x) => x.code === code)) continue;
    const ev = isObj(s) ? str(s.evidence, 20) : '';
    const evidence: SkillEvidence = ev === 'dung' || ev === 'sai' ? ev : ev === 'đúng' ? 'dung' : 'chua-ro';
    skills.push({ code, evidence });
  }
  for (const code of rubric.skills) if (!skills.some((x) => x.code === code)) skills.push({ code, evidence: 'chua-ro' });

  /* ---- lỗi / điểm mạnh ---- */
  const issues: GradeIssue[] = [];
  for (const it of Array.isArray(raw.issues) ? raw.issues.slice(0, 8) : []) {
    const text = isObj(it) ? str(it.text, 300) : str(it, 300);
    if (!text) continue;
    const issue: GradeIssue = { text };
    if (isObj(it)) {
      const sk = str(it.skill, 60);
      if (sk && (allowed.has(sk) || SKILL_BY_CODE[sk])) issue.skill = sk;
      const mc = str(it.misconception, 60);
      if (mc && MISCONCEPTIONS[mc]) issue.misconception = mc;
      const loc = str(it.location, 60);
      if (loc) issue.location = loc;
    }
    issues.push(issue);
  }
  const strengths = (Array.isArray(raw.strengths) ? raw.strengths : []).map((s) => str(s, 200)).filter(Boolean).slice(0, 5);

  /* ---- cờ & độ tin cậy ---- */
  const flags = new Set<GradeFlag>();
  for (const f of Array.isArray(raw.flags) ? raw.flags : []) if (FLAGS.includes(f as GradeFlag)) flags.add(f as GradeFlag);
  let confidence = num(raw.confidence);
  if (confidence === null) {
    repairs.push('thiếu confidence');
    confidence = 0.5;
  }
  if (confidence > 1 && confidence <= 100) confidence /= 100;
  confidence = clamp(confidence, 0, 1);
  if (ctx.imageCount > 0 && transcript.length === 0) {
    repairs.push('thiếu bản chép ảnh');
    confidence = Math.min(confidence, 0.6);
  }
  const missing = repairs.filter((r) => r.startsWith('thiếu tiêu chí')).length;
  if (missing) confidence = Math.max(0, confidence - 0.2 * missing);
  if (repairs.length >= 3) confidence = Math.max(0, confidence - 0.1);
  confidence = Math.round(confidence * 100) / 100;
  if (confidence < GRADE_REVIEW_CONFIDENCE) flags.add('low-confidence');

  /* ---- lời nhận xét ---- */
  let feedbackStudent = sanitizeStudentFeedback(str(raw.feedbackStudent, 800));
  if (!feedbackStudent) {
    repairs.push('thiếu feedbackStudent');
    feedbackStudent = defaultStudentFeedback(level);
  }
  const feedbackTeacher = str(raw.feedbackTeacher, 800) || `Bài đạt ${total}/${max} điểm (${level}).`;
  const feedbackParent = sanitizeStudentFeedback(str(raw.feedbackParent, 800)) || defaultParentFeedback(level);

  const grade: AiGrade = {
    submissionId: ctx.submissionId,
    transcript,
    criteria,
    total,
    max,
    level,
    strengths,
    issues,
    feedbackStudent,
    feedbackTeacher,
    feedbackParent,
    skills,
    confidence,
    flags: FLAGS.filter((f) => flags.has(f)),
    model: ctx.model,
    ...(ctx.mock ? { mock: true } : {}),
    createdAt: ctx.now,
  };
  return { grade, repairs };
}

/** Văn bản AI → AiGrade (parseLooseJson + validateAiGrade). */
export function gradeFromModelText(text: string, ctx: ValidateContext): ValidateResult {
  const { value, repaired } = parseLooseJson(text);
  const r = validateAiGrade(value, ctx);
  if (repaired) r.repairs.unshift('đã sửa định dạng JSON');
  return r;
}
